import { userRoles } from "@hallway/shared";
import { sql } from "drizzle-orm";
import {
  boolean,
  index,
  pgEnum,
  pgTable,
  text,
  timestamp,
} from "drizzle-orm/pg-core";

/**
 * Primary key that says which table it comes from: `user_3f2a9c1e5b7d4e8a9c217d4e5f6a8b90`.
 * Generated by Postgres, so it is also filled for rows inserted outside the app.
 */
const prefixedId = (prefix: string) =>
  text()
    .primaryKey()
    .default(
      sql.raw(`'${prefix}_' || replace(gen_random_uuid()::text, '-', '')`),
    );

/**
 * Default columns of an entity table. Column order in the database follows the order
 * here, so a table starts with `...baseColumns.id("user")` (prefix = singular table
 * name) and ends with `...baseColumns.timestamps`.
 */
const baseColumns = {
  id: (prefix: string) => ({ id: prefixedId(prefix) }),
  timestamps: {
    createdAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp({ withTimezone: true })
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
  },
};

// --- Authentication (Better Auth) ---
// Column set is dictated by Better Auth core + the `admin` plugin; property names must
// stay as Better Auth expects them (the Drizzle adapter addresses columns by property).

export const userRole = pgEnum("user_role", userRoles);

export const users = pgTable("users", {
  ...baseColumns.id("user"),
  name: text().notNull(),
  email: text().notNull().unique(),
  emailVerified: boolean().notNull().default(false),
  image: text(),
  role: userRole().notNull().default("user"),
  banned: boolean().notNull().default(false),
  banReason: text(),
  banExpires: timestamp({ withTimezone: true }),
  notificationsEnabled: boolean().notNull().default(true),
  ...baseColumns.timestamps,
});

export const sessions = pgTable(
  "sessions",
  {
    ...baseColumns.id("session"),
    userId: text()
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    token: text().notNull().unique(),
    expiresAt: timestamp({ withTimezone: true }).notNull(),
    ipAddress: text(),
    userAgent: text(),
    // Set while a superadmin is impersonating this user (admin plugin)
    impersonatedBy: text().references(() => users.id, { onDelete: "set null" }),
    ...baseColumns.timestamps,
  },
  (table) => [index().on(table.userId)],
);

/** Sign-in methods of a user; for e-mail + password the hash lives in `password`. */
export const accounts = pgTable(
  "accounts",
  {
    ...baseColumns.id("account"),
    userId: text()
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    accountId: text().notNull(),
    providerId: text().notNull(),
    accessToken: text(),
    refreshToken: text(),
    idToken: text(),
    accessTokenExpiresAt: timestamp({ withTimezone: true }),
    refreshTokenExpiresAt: timestamp({ withTimezone: true }),
    scope: text(),
    password: text(),
    ...baseColumns.timestamps,
  },
  (table) => [index().on(table.userId)],
);

/** Short-lived tokens: e-mail verification, password reset. */
export const verifications = pgTable(
  "verifications",
  {
    ...baseColumns.id("verification"),
    identifier: text().notNull(),
    value: text().notNull(),
    expiresAt: timestamp({ withTimezone: true }).notNull(),
    ...baseColumns.timestamps,
  },
  (table) => [index().on(table.identifier)],
);
